sys_script_include.script:
var FirewallIntegrationFacade = Class.create();
FirewallIntegrationFacade.prototype = {
    initialize: function(adapterType, params) {
        this.adapter = this._createAdapter(adapterType, params);
        this.schemaUtil = new SchemaUtil(); // Panorama schema parsing utility -- can refactor to be dynamic once new platform is added
        this.importUtil = new FirewallImportUtil(); // shared import handler
    },

    /**
     * Dynamically instantiate adapter based on adapterType
     */
    _createAdapter: function(adapterType, params) {
        switch (adapterType) {
            case "panorama":
                return new PanoramaAdapter(params);
            // case "prisma":
            //     return new PrismaAdapter(params);
            default:
                throw "Unsupported adapter type: " + adapterType;
        }
    },

    /**
     * Orchestrates object retrieval from firewall, ETLs the payload, then passes expected format to Import Set API. The Import Multiple endpoint of the Import Set API accepts JSON in the following format:
     * {
     * records [
     * {"name" : "string", "values" : "1,2,3"},
     * {"name" : "string", "values" : "1,2,3"},
     * ]
     * }
     */
    runImportUtil: function(schemaName, queryParams) {
        var schema = new SchemaRegistry().getSchema(schemaName);
		gs.info("Completed fetching schema:  " + JSON.stringify(schema));
        if (!schema)
            throw "Schema not found: " + schemaName;

        // Step 1: Fetch raw payload
        var fetchResult = this.adapter.fetchObjects(schema.httpMethod, queryParams, schema);
        if (!fetchResult.success)
            return { success: false, error: fetchResult.error };

		gs.info("fetch result completed successfully: " + JSON.stringify(fetchResult.payload));

        // Step 2: Parse payload via SchemaUtil
        var parsed = this.schemaUtil.parseResponse(fetchResult.payload, schema.map);
		gs.info("parsing complete: " + JSON.stringify(parsed.records));

        // Step 3: Deduplicate if schema requires it
        if (schema.dedupe)
            parsed.records = this.schemaUtil.dedupe(parsed.records, schema.key);

        // Step 4: Send parsed records to import table
        var importResult = this.importUtil.sendToImportSet(parsed.records, schema.table);

        // return {
        //     success: importResult.success,
        //     message: importResult.message || "Import complete"
        // };
    },

    type: "FirewallIntegrationFacade"
};
